"""
This file introducing the control matching method that can matching the controls that in same line. Because sometime when we to
access the control that does not have a name to tell which one it is, but another control with name is in the same line, by matching
them we can easily reference either of them.
"""

from pyjab.jabelement import JABElement

def same_line_control_matching(named_controls:list, another_controls:list, max_midline_diff=1):
    """
    Inputs are two list of control objects(for example labels and comboboxes), and matching criterion--midline diff.
    The matching with additional constraints:
    1. Sort by midline height
    2. Allow matching within a small vertical tolerance
    3. Prefer closest matches
    returns a dict of them, the key is the name of controls from 1st list which have names(e.g., Label's name ) and the value is
    the control that may not have name of the second list(e.g. combo box)
    """
    def calculate_midline(e:JABElement):
        return e.bounds["y"] + e.bounds["height"] / 2

    matches = {}
    used_labels = set()

    # Sort comboboxes by midline
    sorted_another_controls = sorted(another_controls, key=calculate_midline)

    for another_control in sorted_another_controls:
        another_control_midline = calculate_midline(another_control)

        # Find the best matching label
        best_match = None

        for named_control in named_controls:
            if named_control in used_labels:
                continue

            named_control_midline = calculate_midline(named_control)
            midline_diff = abs(another_control_midline - named_control_midline)

            # Check if within acceptable difference
            if midline_diff <= max_midline_diff:
                best_match = named_control
                break

        # Add match if found
        if best_match:
            matches.update({best_match.name: another_control})
            used_labels.add(best_match)

    return matches
